function frame(now){audio.tick();const economyDt=lastEconomy?Math.min(.05,Math.max(0,(now-lastEconomy)/1000)):0;lastEconomy=now;if(burstPointer!==null&&progression.features.burst&&!treeOpen&&pageFocused&&!document.hidden&&!ads.active){burstCharge+=economyDt;if(burstCharge>=.22){burstCharge-=.22;hyperPulse();}}progression.tickEconomy(economyDt,!treeOpen&&pageFocused&&!document.hidden&&(game.state!=='paused'||ads.active));if(ads.active||treeOpen){cancelBurst();last=now;requestAnimationFrame(frame);return;}const dt=last?Math.min((now-last)/1000,.035):0;last=now;if(game.state==='running'){tick+=dt;game.update(dt);}else if(game.state==='ready'&&!lowMotion)tick+=dt;if(game.state!=='paused'){for(const r of rings)r.life-=dt;rings=rings.filter(r=>r.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);for(const t of texts){if(!lowMotion)t.y-=dt*28;t.life-=dt;}texts=texts.filter(t=>t.life>0);}render();if(now-lastHud>60){hud();lastHud=now;}requestAnimationFrame(frame);}hud();requestAnimationFrame(frame);
